namespace Aw.Sindri.Core.Views;

/// <summary>
/// The view schema version: bump it when a projection's fold changes or a view row record's shape does, and the projector rebuilds the views
/// from the ledger on the next start. A test pins the row shapes to this number, so a shape change without a bump fails the build.
/// </summary>
public static class ViewSchema
{
    /// <summary>The version this build folds with (37: the workflow-runs row carries Mode, live or test (Workflows page spec §3.2); 36: the needs-you row has a decision member, joined at read time and null in the stored view (#2789); 35: the items view has a state column (#2788); 34: the launches view has reason and instance columns, so the idle count reads the idle launches and not every launch (#2786); 33: the workflow question rows carry the loop item of an 'ask_owner' node in a 'for_each' body (#2543); 31: the launches view has run_id and node_id columns and the launch row's step carries the graph run and node (issue 2258, PR 7); 30: the item-links view joined, recipe-stats left and the engine part left the items row (v2 PR 4b); 29: the recipe engine is gone (#2258), and the row-shape hash covers the types the rows hold, no fold change; 28: the graph runs view (issue 2258, PR 6); 27: the needs-you row carries the connection kind (connections PR 10b, #2258); 26: the todo view (todo spec §4.2); 25: the launch-id types moved namespace (Core.Launch), which the row-shape hash covers, no fold change (#2258); 24: the jobs row keeps its last 200 model calls and counts fallbacks (context model routing R-4, #1567); 23: the project-attached row carries notes (free text) in place of the one-line note (owner q158); 22: the jobs row carries its model totals and the signal it waits on (context model routing, #1567); 21: the project-attached and project-hidden views (projects page Ph3); 20: a park row carries its sandbox refusal in the owner's words (SB-6); 19: the launch row carries the sandbox summary from launch.started (sandbox SB-6); 18: the model-history fold keys a mirrored row by the workflow id, so history rows a real run never wrote are now written (#1481); 17: the launch row carries the model from launch.started (#1008); 16: a parked suspension carries its sandbox marker and the launch and self-check park kinds (U9, #1113); 15: the model-history and model-runs views (model-pick M-4); 14: the launch row carries the sandbox failure reason, source and limit ending from launch.failed's detail (sandbox SB-0, spec rev 7); 13: the services row carries pausedBy/pausedAt and lastRun.detail (B-15); 12: the launch row folds launch.takeover-opened (viewer, attach) (#1004); 11: the engine item part carries the unavailable park (#1001); 10: NeedsYouRow.Open became required, and the row shapes are pinned (#959); 9: the code-index view; 8: API P12's recipe stats cache; 7: launch rows carry the instance, Step and attempt; 6: API P10a's launches view; 5: API P11's engine item states; 4: API P6's jobs view and the failure row's new cli; 3: API P4's request, decision and needs-you views).</summary>
    public const int Version = 37;
}
